import fs from 'node:fs';
const args = process.argv.slice(2);
if (args.length === 1 && args[0] === '--help') {
  console.log('Usage: node total.mjs <input.json>\nOutput: {totals:{currency:minorUnits},unresolved:[recordIndex]}. Exit: 0 success; 2 invalid input.');
} else {
  try {
    if (args.length !== 1) throw new Error('provide one JSON input file; use --help');
    const rows = JSON.parse(fs.readFileSync(args[0], 'utf8'));
    if (!Array.isArray(rows)) throw new Error('expected an array');
    const sums = new Map(), unresolved = [];
    rows.forEach((row, i) => {
      if (!row || typeof row.currency !== 'string' || !/^[A-Z]{3}$/.test(row.currency) || !Number.isSafeInteger(row.amountMinor)) { unresolved.push(i); return; }
      const total = (sums.get(row.currency) ?? 0) + row.amountMinor;
      if (!Number.isSafeInteger(total)) { unresolved.push(i); return; }
      sums.set(row.currency, total);
    });
    console.log(JSON.stringify({totals:Object.fromEntries(sums),unresolved}));
  } catch (e) { console.error(e.message); process.exitCode = 2; }
}
